    LANGUAGE_WRAPPER = 'Let $S_{{n}}$ be the set of positive integers that can be expressed in the form $\\sum_{k=1}^{{n}} \\lfloor kx \\rfloor$ for some non-negative real number $x$. How many integers in the set $\\{1, 2, \\dots, {N}\\}$ are elements of $S_{{n}}$?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
n = rng.randint(9, 13)
Sn = n * (n + 1) // 2
# N should be large enough to have several blocks of Sn
# and not be a multiple of Sn to test the remainder part
# Let's target N between 4000 and 20000
min_q = 4000 // Sn
if min_q == 0: min_q = 1
max_q = 20000 // Sn
q = rng.randint(min_q, max_q)
r = rng.randint(1, Sn - 1)
N = q * Sn + r
return {'n': n, 'N': N}

    def verifier(assign):
n = assign['n']
N = assign['N']

if not (9 <= n <= 13):
    return False, None # n is out of the specified range

S_n = n * (n + 1) // 2

if not (4000 <= N <= 20000):
    return False, None # N is out of range
if N % S_n == 0:
    # This case is simpler and avoided by the generator to ensure testing the main logic.
    return False, None 

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

gaps = set()
for q_den in range(2, n + 1):
    jump_size = n // q_den
    if jump_size <= 1:
        continue

    num_gaps_per_p = jump_size - 1

    for p_num in range(1, q_den):
        if gcd(p_num, q_den) == 1:
            f_p_q = sum(k * p_num // q_den for k in range(1, n + 1))
            for i in range(1, num_gaps_per_p + 1):
                gaps.add(f_p_q - i)

# The set of values for x in [0, 1) is R_n, which is a subset of [0, S_n - n].
# The integers not in R_n are the gaps.
# The set of excluded residues mod S_n are the gaps plus all integers from S_n - n + 1 to S_n - 1.
max_val_in_unit_interval = S_n - n

excluded_residues = set()
for g in gaps:
    # We only care about positive residues, and gaps are positive.
    excluded_residues.add(g)

for i in range(max_val_in_unit_interval + 1, S_n):
    excluded_residues.add(i)

# Count numbers up to N with excluded residues.
q_div = N // S_n
r_rem = N % S_n

num_excluded_le_r = 0
for e in excluded_residues:
    if 1 <= e <= r_rem:
        num_excluded_le_r += 1

excluded_count = num_excluded_le_r * (q_div + 1) + (len(excluded_residues) - num_excluded_le_r) * q_div

